{
  "status": "SUPPORTED",
  "task_summary": "Prepare living room for two people with refreshment settings and accessible entertainment control.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_item",
        "entity_kind": "OBJECT",
        "function": "holds liquid or food for consumption",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      , "candidate_categories": ["cup", "glass", "plate", "bowl"]
      , "required_properties": ["contains edible or drinkable content"]
      }
    , {
        "id": "surface",
        "entity_kind": "REGION",
        "function": "provides a flat destination for items",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      , "candidate_categories": ["tabletop", "desk surface", "shelf surface"]
      , "required_properties": ["flat", "stable", "horizontal"]
      }
    , {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "controls the television",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      , "candidate_categories": ["remote", "controller", "mouse"]
      , "required_properties": ["input device"]
      }
    , {
        "id": "television",
        "entity_kind": "FIXED_TARGET",
        "function": "fixed reference point for viewing",
        "required_count": 1,
        "binding_policy": "SHARED"
      , "candidate_categories": ["screen", "TV", "monitor"]
      , "required_properties": ["display"]
      }
    ],
    "functional_relations": [
      {
        "id": "holds_refreshment",
        "relation": "surface holds refreshment_item",
        "participant_roles": ["surface", "refreshment_item"]
      , "required": true
      }
    , {
        "id": "accessible_to_view",
        "relation": "entertainment_control is near television",
        "participant_roles": ["entertainment_control", "television"]
      , "required": true
      }
    , {
        "id": "near_viewing_area",
        "relation": "surface is near television",
        "participant_roles": ["surface", "television"]
      , "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "provide_refreshment_setting",
        "operation": "place refreshment_item on surface",
        "participant_roles": ["refreshment_item", "surface"]
      , "operation_count": 2
      }
    , {
        "id": "position_entertainment_control",
        "operation": "move entertainment_control to surface",
        "participant_roles": ["entertainment_control", "surface"]
      , "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_item": [
        {"label": "red cup", "visual_description": "red cup on coffee table"},
        {"label": "white plate", "visual_description": "white plate on left side table"},
        {"label": "red cup", "visual_description": "red cup on large desk"},
        {"label": "white plate", "visual_description": "white plate on large desk"}
      ],
      "surface": [
        {"label": "coffee table", "visual_description": "center table with green top"},
        {"label": "left side table", "visual_description": "wooden table next to left chair"},
        {"label": "right side table", "visual_description": "wooden table next to right chair"},
        {"label": "console table", "visual_description": "table under TV"},
        {"label": "large desk", "visual_description": "desk in foreground right"}
      ],
      "entertainment_control": [
        {"label": "remote", "visual_description": "black remote on large desk"}
      ],
      "television": [
        {"label": "TV screen", "visual_description": "black screen mounted on wall"}
      ]
    },
    "inspectable_regions": [],
    "inspection_order": []
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
  }
